# Generated by Claude (Claude Code).
"""LDA of PeakCNN's 32 features: directions fitted on a separate set (seed 54321), test set (seed 12345)
projected and drawn like pca_single.py (blue/green/red per true peak count, shades per pattern).
Usage: python lda_features.py <project dir> <run dir> <out png>"""
import json, sys, warnings
from pathlib import Path
import numpy as np
import torch, torch_directml
from scipy.linalg import eigh
from matplotlib import rc_context
from matplotlib.figure import Figure
from matplotlib.lines import Line2D

project, run, out = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]
sys.path.insert(0, str(project))
import data  # noqa: E402
from model import NUM_SAMPLES, PeakCNN  # noqa: E402
from plot import AXIS, GRIDLINE, RC, SURFACE, TEXT_MUTED, TEXT_PRIMARY, TEXT_SECONDARY  # noqa: E402
warnings.filterwarnings("ignore")
data.WARP, data.MIN_KNOT_DISTANCE = "cubic", 0.05
N = 51_200
dev = torch_directml.device()
cfg = json.loads((run / "config.json").read_text())
OPTIMIZER_NAMES = {"adam": "Adam", "adam_amsgrad": "AMSGrad", "schedule_free_adamw": "Schedule-Free AdamW", "sgd": "SGD"}
optimizer = OPTIMIZER_NAMES.get(cfg["optimizer"], cfg["optimizer"])
model = PeakCNN(NUM_SAMPLES, cfg["channels"])
model.load_state_dict(torch.load(run / "model.pt", weights_only=True))
model.to(dev).eval()


def dataset(seed):
    f, y = data.generate_batch(N, NUM_SAMPLES, np.random.default_rng(seed))
    rng = np.random.default_rng(seed)
    lab = rng.integers(0, 3, N)
    pats = []
    for label in lab:
        ps = data.PATTERNS[label]
        p = ps[rng.integers(len(ps))]
        data.sample_params(p, rng)
        pats.append(p)
    feats, preds = [], []
    with torch.no_grad():
        for k in range(0, N, 1024):
            h = torch.flatten(model.features(torch.from_numpy(f[k:k + 1024]).to(dev).unsqueeze(1)), 1)
            feats.append(h.cpu().numpy()); preds.append(model.classifier(h).argmax(1).cpu().numpy())
    return np.concatenate(feats).astype(np.float64), y, np.array(pats), np.concatenate(preds)


Xf, yf, _, _ = dataset(54321)
Xt, yt, pt, predt = dataset(12345)
live = Xf.std(0) > 0  # dead ReLU channels (always 0) make the within-class scatter singular
mu = Xf[:, live].mean(0)
Sw = np.zeros((live.sum(), live.sum())); Sb = np.zeros_like(Sw)
means = []
for c in range(3):
    Xc = Xf[yf == c][:, live]
    mc = Xc.mean(0); means.append(mc)
    Sw += (Xc - mc).T @ (Xc - mc)
    Sb += len(Xc) * np.outer(mc - mu, mc - mu)
evals, evecs = eigh(Sb, Sw)
idx = np.argsort(evals)[::-1][:2]
W = evecs[:, idx]
pooled = Sw / (len(Xf) - 3)
W /= np.sqrt(np.einsum("ij,jk,ki->i", W.T, pooled, W))  # unit pooled within-class std per axis
proj = lambda X: (X[:, live] - mu) @ W
Pt, Pf = proj(Xt), proj(Xf)
share = evals[idx] / evals[idx].sum()
# How separable are the classes in this 2D view? Nearest class mean (equal covariances) on the test set.
cm = np.array([Pf[yf == c].mean(0) for c in range(3)])
nearest = np.argmin(((Pt[:, None, :] - cm[None]) ** 2).sum(-1), 1)
print(f"live channels {int(live.sum())} of 32; discriminant ratios {np.round(evals[idx], 2).tolist()}, "
      f"share of between-class separation {np.round(100 * share, 1).tolist()} %")
print(f"test set: nearest-class-mean accuracy in the 2D LDA plane {np.mean(nearest == yt):.3%}; model {np.mean(predt == yt):.3%}")
for c in range(3):
    print(f"   class {c}: test mean {np.round(Pt[yt == c].mean(0), 2).tolist()}, std {np.round(Pt[yt == c].std(0), 2).tolist()}")

SHADES = {"": "#1f3fbf", "V": "#6f8fff", "P": "#0b6b1f", "VP": "#1f9f3a", "PV": "#4cc35c", "VPV": "#93df8f",
          "PVP": "#8b0000", "VPVP": "#c81e1e", "PVPV": "#f05050", "VPVPV": "#ff9c8c"}
order = np.random.default_rng(0).permutation(N)
with rc_context(RC):
    fig = Figure(figsize=(11, 8), dpi=160, facecolor=SURFACE)
    ax = fig.add_subplot()
    ax.set_facecolor(SURFACE)
    ax.scatter(Pt[order, 0], Pt[order, 1], s=1.4, c=np.array([SHADES[p] for p in pt])[order], linewidths=0,
               alpha=0.8, rasterized=True)
    ax.set_aspect("equal", adjustable="datalim")
    ax.set_xlabel(f"LD1 ({100 * share[0]:.1f}% of the class separation, in within-class standard deviations)",
                  color=TEXT_SECONDARY)
    ax.set_ylabel(f"LD2 ({100 * share[1]:.1f}%)", color=TEXT_SECONDARY)
    ax.grid(color=GRIDLINE, linewidth=1); ax.set_axisbelow(True)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(AXIS)
    ax.tick_params(colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=6)
    handles = []
    for cls, name in ((0, "0 peaks"), (1, "1 peak"), (2, "2 peaks")):
        handles.append(Line2D([], [], linestyle="none", label=name))
        for p, col in SHADES.items():
            if p.count("P") == cls:
                handles.append(Line2D([], [], marker="o", linestyle="none", markersize=7, color=col,
                                      label=f"  {p or '(none)'}  ({int(np.sum(pt == p)):,})"))
    leg = ax.legend(handles=handles, loc="upper left", bbox_to_anchor=(1.01, 1.0), frameon=False,
                    handletextpad=0.4, borderaxespad=0)
    for text, h in zip(leg.get_texts(), handles):
        heading = h.get_marker() in (None, "None", "")
        text.set_color(TEXT_PRIMARY if heading else TEXT_SECONDARY)
        if heading:
            text.set_fontweight("semibold")
    fig.suptitle(f"LDA of the 32 features of the cubic-warp model ({optimizer}, {cfg['epochs']} epochs)", x=0.08, y=0.965, ha="left", fontsize=13,
                 fontweight="semibold", color=TEXT_PRIMARY)
    fig.text(0.08, 0.925, "directions fitted on 51,200 functions (seed 54321), shown for the 51,200 test functions "
             f"(seed 12345, cubic warp, minimum distance 0.05) · run {run.name} · colour: true peak count, "
             "shade: pattern", ha="left", fontsize=9, color=TEXT_SECONDARY)
    fig.subplots_adjust(left=0.08, right=0.8, top=0.88, bottom=0.08)
    fig.savefig(out, facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)
print("saved", out)
